{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table RPSG_DB.MAPLEMONK.Product_Sales_Cost_Source_Ecom_DRV as with invoicedatemetrics as ( select try_to_date(FI.invoice_date) Invoice_Date ,FI.sku ,upper(FI.SHOP_NAME) SHOP_NAME ,count(distinct case when lower(order_status) not in (\'cancelled\') then order_id end ) pre_invoice_Delivered_Orders ,count(distinct case when lower(order_status) not in (\'cancelled\') and lower(new_customer_flag) = \'repeat\' then order_id end ) pre_repeat_invoice_Delivered_Orders ,sum(ifnull((case when lower(order_status) not in (\'cancelled\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0)) Realised_Revenue ,sum(ifnull((case when lower(order_status) not in (\'cancelled\') and lower(new_customer_flag) = \'repeat\' then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0)) repeat_Realised_Revenue ,sum(ifnull((case when lower(order_status) not in (\'cancelled\') and lower(payment_mode) = \'prepaid\' then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0)) Prepaid_Realised_Revenue from RPSG_DB.MAPLEMONK.SALES_CONSOLIDATED_ECOM_DRV FI where not(lower(order_status) in (\'cancelled\')) and invoice_date != \'\' group by 1,2,3 order by 1 desc ), returnsales as ( SELECT return_date::date AS return_date, CASE WHEN UPPER(b.marketplace) LIKE \'%AMAZON%\' THEN \'AMAZON\' WHEN UPPER(b.marketplace) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN UPPER(b.marketplace) LIKE \'%MEESHO%\' THEN \'MEESHO\' WHEN UPPER(b.marketplace) LIKE \'%JIO MART%\' THEN \'JIOMART\' WHEN UPPER(b.marketplace) LIKE \'%CRED%\' THEN \'CRED\' WHEN UPPER(b.marketplace) LIKE \'%GOQII%\' THEN \'GOQII\' WHEN UPPER(b.marketplace) LIKE \'%HEALTH MUG%\' THEN \'HEALTH MUG\' WHEN UPPER(b.marketplace) LIKE \'%HEALTHXP%\' THEN \'HEALTHXP\' WHEN UPPER(b.marketplace) LIKE \'%HEALTH KART%\' THEN \'HEALTH KART\' WHEN UPPER(b.marketplace) LIKE \'%MYNTRA%\' THEN \'MYNTRA\' WHEN UPPER(b.marketplace) LIKE \'%NATUREFIT%\' THEN \'NATUREFIT\' WHEN UPPER(b.marketplace) LIKE \'%PHARMEASY%\' THEN \'PHARMEASY\' WHEN UPPER(b.marketplace) LIKE \'%SMYTTEN%\' THEN \'SMYTTEN\' WHEN UPPER(b.marketplace) LIKE \'%SNAPDEAL%\' THEN \'SNAPDEAL\' WHEN UPPER(b.marketplace) LIKE \'%TELEONE%\' THEN \'TELEONE\' WHEN UPPER(b.marketplace) LIKE \'%NATUREFIT%\' THEN \'NATUREFIT\' WHEN UPPER(b.marketplace) LIKE \'%TRELL%\' THEN \'TRELL\' WHEN UPPER(b.marketplace) LIKE \'%WMALL%\' THEN \'WMALL\' WHEN UPPER(b.marketplace) LIKE \'%1MG%\' THEN \'1MG\' ELSE UPPER(b.marketplace) END AS shop_name, b.sku, SUM(CASE WHEN LOWER(new_customer_flag) = \'repeat\' THEN return_amount_without_tax ELSE 0 END) AS repeat_return_amount_excl_tax, SUM(CASE WHEN LOWER(booked_customer_flag) = \'repeat\' THEN return_amount_without_tax ELSE 0 END) AS booked_repeat_return_amount_excl_tax, SUM(TOTAL_RETURN_AMOUNT) AS TOTAL_RETURN_AMOUNT, SUM(return_amount_without_tax) AS TOTAL_RETURN_AMOUNT_EXCL_TAX, SUM(returned_quantity) AS TOTAL_RETURNED_QUANTITY FROM (SELECT * FROM RPSG_DB.MAPLEMONK.fact_items_easyecom_returns_detailed_drv WHERE UPPER(marketplace) LIKE ANY (\'%AMAZON%\', \'%FLIPKART%\', \'%MEESHO%\', \'%JIO MART%\', \'%PHARMEASY%\',\'%CRED%\', \'%SNAPDEAL%\', \'%HEALTH MUG%\', \'%SMYTTEN%\', \'%GOQII%\', \'%FIRSTCRY%\', \'%TELEONE%\', \'%TRELL%\', \'%WMALL%\' , \'%1MG%\' , \'%NATUREFIT%\',\'%MYNTRA%\' ,\'%HEALTHXP%\' ,\'%HEALTH KART%\') ) b LEFT JOIN ( SELECT * FROM ( SELECT SKU, BRAND, CATEGORY, MARKETPLACE AS maketplace_map, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, ROW_NUMBER() OVER (PARTITION BY LOWER(MARKETPLACE), LOWER(sku) ORDER BY 1) AS rw FROM rpsg_db.maplemonk.amazon_asin_amazon_asin WHERE sku IS NOT NULL AND LOWER(brand) LIKE \'%drv%\' ) WHERE rw = 1 ) S ON LOWER(b.sku) = LOWER(s.sku) AND LOWER(S.maketplace_map) = LOWER( CASE WHEN POSITION(\' \', b.marketplace) > 0 THEN SPLIT(b.marketplace, \' \')[0] ELSE SPLIT(b.marketplace, \'_\')[0] END ) WHERE s.sku IS NOT NULL GROUP BY 1, 2, 3 ORDER BY 1 DESC ), orders as ( select FI.order_date::date Date ,upper(FI.marketplace) SHOP_NAME ,sku ,count(distinct case when lower(payment_mode) = \'cod\' then order_id end) cod_Orders ,count(distinct case when lower(payment_mode) = \'prepaid\' then order_id end) prepaid_Orders ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) Total_Sales ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) - ifnull(sum(FI.tax),0) TOTAL_SALES_EX_TAX ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.SELLING_PRICE end),0) TOTAL_SALES_EXCL_CANCL ,count(distinct FI.order_id) Total_Orders ,count(distinct FI.order_id) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.order_id end) Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) as New_Customer_Orders ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) - count(distinct(case when lower(FI.new_customer_flag) = \'new\' and lower(FI.order_status) in (\'cancelled\') then FI.order_id end)) as New_Customer_Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.customer_id_final end)) as Total_New_Customers ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.customer_id_final end)) - count(distinct(case when lower(FI.new_customer_flag) = \'new\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.customer_id_final end)) New_Customers_EXCL_CANCL ,count(distinct FI.customer_id_final) as TOTAL_Unique_Customers ,(count(distinct FI.customer_id_final) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.customer_id_final end)) as Unique_Customers_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.customer_id_final end)) as Repeat_Customers ,(count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.customer_id_final end)) - count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.customer_id_final end))) Repeat_Customers_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.order_id end)) as Repeat_Orders ,sum(case when lower(FI.new_customer_flag) = \'repeat\' then ifnull(FI.selling_price,0) end) as Repeat_Revenue ,(count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then Fi.order_id end)) - count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.order_id end))) Repeat_orders_EXCL_CANCL ,ifnull(sum(FI.discount_mrp),0) TOTAL_DISCOUNT ,(ifnull(sum(FI.discount_mrp),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.discount_mrp end),0)) TOTAL_DISCOUNT_EXCL_CANCL ,ifnull(sum(FI.tax),0) TOTAL_TAX ,(ifnull(sum(FI.tax),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.tax end),0)) TAX_EXCL_CANCL ,ifnull(sum(FI.shipping_price),0) TOTAL_SHIPPING_PRICE ,(ifnull(sum(FI.shipping_price),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.shipping_price end),0)) SHIPPING_PRICE_EXCL_CANCL ,ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' then FI.discount_mrp end),0) as New_Customer_Discount ,(ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' then FI.discount_mrp end),0) - ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' and lower(order_status) in (\'cancelled\') then FI.discount_mrp end),0)) as New_Customer_Discount_EXCL_CANCL ,ifnull(sum(FI.suborder_quantity),0) TOTAL_QUANTITY ,(ifnull(sum(FI.suborder_quantity),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.suborder_quantity end),0)) QUANTITY_EXCL_CANCL ,ifnull(sum(case when FI.return_flag=1 then FI.suborder_quantity end),0) as Return_Quantity ,ifnull(sum(case when FI.return_flag=1 then ifnull(FI.SELLING_PRICE,0) end),0) as Return_Value ,count(distinct case when FI.return_flag=1 then order_id end )as Return_Orders ,count(distinct case when lower(order_status) in (\'cancelled\') then order_id end) Cancelled_Orders ,count(distinct case when lower(order_status) not in (\'cancelled\') and return_flag=0 then order_id end) Net_Orders ,count(distinct case when lower(final_status) in (\'delivered\') then order_id end) Delivered_Orders ,count(distinct case when lower(final_status) in (\'returned\',\'rto\') or lower(final_status) in (\'returned\',\'rto\') then order_id end) Returned_Orders ,count(distinct case when manifest_date is not null and lower(order_status) not in (\'cancelled\') then order_id end) Dispatched_Orders ,Orders_EXCL_CANCL - Returned_Orders as Realised_Orders ,ifnull(sum(case when lower(final_status) in (\'delivered\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0) Delivered_Revenue ,ifnull(sum(case when lower(final_status) in (\'returned\',\'rto\') or lower(final_status) in (\'returned\',\'rto\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0) Returned_Revenue ,ifnull(sum(case when manifest_date is not null and lower(order_status) not in (\'cancelled\') then ifnull(FI.SELLING_PRICE,0) end),0) Dispatched_Revenue ,count(case when date_trunc(\'month\',acquisition_date)>=dateadd(month,-3,date_trunc(\'month\',order_date)) and date_trunc(\'month\',acquisition_date)<date_trunc(\'month\',order_date) then customer_id_final end) L3M_Customers_Retained ,count(case when date_trunc(\'month\',acquisition_date)>=dateadd(month,-6,date_trunc(\'month\',order_date)) and date_trunc(\'month\',acquisition_date)<date_trunc(\'month\',order_date) then customer_id_final end) L6M_Customers_Retained ,count(case when date_trunc(\'month\',acquisition_date)>=dateadd(month,-3,date_trunc(\'month\',order_date)) and date_trunc(\'month\',acquisition_date)<date_trunc(\'month\',order_date) then customer_id_final end) L12M_Customers_Retained ,sum(case when lower(FI.new_customer_flag_month) = \'repeat\' then ifnull(FI.selling_price,0) end) Repeat_Customer_Revenue from RPSG_DB.MAPLEMONK.SALES_CONSOLIDATED_ECOM_DRV FI group by 1,2,3 ), spend as ( select date, case when upper(channel) like \'%AMAZON%\' then \'AMAZON\' when upper(channel) like \'%FLIPKART%\' then \'FLIPKART\' else upper(channel) end as shop_name ,coalesce(s.sku,mc.sku,\'others\') sku ,sum(spend) as spend ,sum(ifnull(impressions,0)) as impressions ,sum(ifnull(clicks,0)) as clicks ,sum(ifnull(AD_REVENUE_EXC_TAX,0)) as AD_REVENUE_EXC_TAX ,sum(conversions) as conversions ,sum(conversion_value) as conversion_value from(select * from RPSG_DB.MAPLEMONK.MARKETING_CONSOLIDATED_DRV WHERE lower(channel) like any (\'%amazon%\',\'%flipkart%\', \'%meesho%\')) mc left join ( select * from (select SKU, BRAND, CATEGORY, MARKETPLACE as maketplace_map, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, row_number() over (partition by lower(sku) order by 1) rw from rpsg_db.maplemonk.amazon_asin_amazon_asin where sku is not null and lower(brand) like \'%drv%\') where rw=1 and lower(maketplace_map) like any (\'%amazon%\', \'%flipkart%\', \'%meesho%\') and MARKETPLACE_SKU is not null ) S on lower(mc.sku) = lower(s.MARKETPLACE_SKU) and lower(mc.CHANNEL) = lower(s.maketplace_map) group by 1,2,3 order by 1 desc ), all_metrics as ( select coalesce(fi.Date,MC.date, RS.Return_Date, ID.invoice_date) as date, upper(coalesce(FI.Shop_Name, MC.shop_name, RS.Shop_name, ID.Shop_name)) as Marketplace, upper(coalesce(FI.sku, MC.sku, RS.sku, ID.sku)) as sku, cod_orders, prepaid_orders, Total_Sales, TOTAL_SALES_EX_TAX, TOTAL_SALES_EXCL_CANCL, Total_Orders, Orders_EXCL_CANCL, New_Customer_Orders, New_Customer_Orders_EXCL_CANCL, Total_New_Customers, New_Customers_EXCL_CANCL, TOTAL_Unique_Customers, Unique_Customers_EXCL_CANCL, Repeat_Customers, Repeat_Customers_EXCL_CANCL, Repeat_orders, Repeat_Revenue, Repeat_orders_EXCL_CANCL, TOTAL_DISCOUNT, TOTAL_DISCOUNT_EXCL_CANCL, TOTAL_TAX, TAX_EXCL_CANCL, TOTAL_SHIPPING_PRICE, SHIPPING_PRICE_EXCL_CANCL, New_Customer_DISCOUNT, New_Customer_Discount_EXCL_CANCL, TOTAL_QUANTITY, QUANTITY_EXCL_CANCL, RS.TOTAL_RETURNED_QUANTITY as Return_Quantity, RS.TOTAL_RETURN_AMOUNT_EXCL_TAX as Return_Value, Cancelled_Orders, return_Orders, Net_Orders, Delivered_Orders, Delivered_Revenue, Dispatched_Orders, Dispatched_Revenue, Realised_Orders, ifnull(ID.Realised_Revenue,0)- ifnull(RS.TOTAL_RETURN_AMOUNT_EXCL_TAX,0) as Realised_Revenue, ifnull(ID.repeat_Realised_Revenue,0)- ifnull(RS.repeat_return_amount_excl_tax,0) as repeat_Realised_Revenue, ifnull(ID.Realised_Revenue,0) Invoice_Amount_Excl_Tax, MC.spend, CASE WHEN upper(coalesce(FI.Shop_Name, MC.shop_name, RS.Shop_name, ID.Shop_name)) = \'GOQII\' THEN (((ifnull(ID.Realised_Revenue,0)- ifnull(RS.TOTAL_RETURN_AMOUNT_EXCL_TAX,0))/1.3)) ELSE spend END AS marketing_spend, impressions, clicks, AD_REVENUE_EXC_TAX, conversions, conversion_value from orders FI full outer join spend MC on FI.Date = MC.date and lower(FI.sku) = lower(MC.sku) and lower(FI.Shop_name)=lower(MC.Shop_name) full outer join returnsales RS on RS.return_date = coalesce(FI.Date,MC.Date) and lower(RS.sku) = lower(coalesce(FI.sku,MC.sku)) and lower(RS.Shop_name)=lower(coalesce(FI.Shop_name, MC.Shop_name)) full outer join invoicedatemetrics ID on ID.invoice_date = coalesce(FI.Date,MC.Date, RS.return_date) and lower(coalesce(FI.sku,MC.sku,RS.sku))=lower(ID.sku) and lower(coalesce(FI.Shop_name, MC.Shop_name, RS.Shop_name))=lower(ID.Shop_name) ) select a.*,coalesce(b.PRODUCT_NAME,c.PRODUCT_NAME) as PRODUCT_NAME ,coalesce(b.CATEGORY,c.category) as CATEGORY from all_metrics a left join ( select * from (select SKU, BRAND, CATEGORY, MARKETPLACE as maketplace_map, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, row_number() over (partition by lower(sku) order by 1) rw from rpsg_db.maplemonk.amazon_asin_amazon_asin where sku is not null and lower(brand) like \'%drv%\') where rw=1 )b on lower(a.sku) = lower(b.sku) left join ( select * from (select SKU, BRAND, CATEGORY, MARKETPLACE as maketplace_map, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, row_number() over (partition by lower(MARKETPLACE_SKU) order by 1) rw from rpsg_db.maplemonk.amazon_asin_amazon_asin where MARKETPLACE_SKU is not null and lower(brand) like \'%drv%\') where rw=1 )c on lower(a.sku) = lower(c.MARKETPLACE_SKU) ;",
